import React from 'react';
import clsx from 'clsx';

import { useMessagePermissions } from './hooks/useMessagePermissions';
import { useTranslationContext } from '../../context/TranslationContext';
import { useMessageContext } from '../../context';

export const MessageBlocked = () => {
  const { message } = useMessageContext();
  const { t } = useTranslationContext();

  const { isMyMessage } = useMessagePermissions(message);

  const messageClasses = clsx(
    'str-chat__message str-chat__message--blocked',
    message.type,
    {
      'str-chat__message--me': isMyMessage,
      'str-chat__message--other': !isMyMessage,
    },
  );

  return (
    <div
      className={messageClasses}
      data-testid='message-blocked-component'
      key={message.id}
    >
      <div className='str-chat__message--blocked-inner'>
        {t('message.blocked.text', 'Message was blocked by moderation policies')}
      </div>
    </div>
  );
};
